//SOUND_BEGIN
// =========================================================================
// Title: Trailing the Twinkling Tunnelwisp (Audio)
// Original Music: Pestis (Cassini's Cosmic Conclusion - demozoo.org/productions/367582/)
// 
// License: CC0 1.0 Universal (Public Domain Dedication)
//          https://creativecommons.org/publicdomain/zero/1.0/
//
// Note: Adapted for the "Surfaces Explorer" engine.
// =========================================================================

vec2 mainSound(int s, float t) {
  vec2 r = vec2(0.0); // FIX 1: Inizializzato a zero

  // FIX 2: i e j inizializzati a zero
  for(float i = 0.0, j = 0.0; ++i < 4.0;)
  for(j = 0.0; ++j < 5.0;) {

    float a = t * j / 32.0 + i / 3.0;
    float b = fract(a);
    float c;

    // FIX 3: m inizializzato a zero
    vec2 m = vec2(0.0); 
    vec2 n = vec2(t, t + 3.0) + t / j;

    for(c = 3.0; c < 4.1; n += c *= 1.02)
      m += sin(n * c) / c;

    if(a < 9.0)
      r += sin(m + 4.0 * sin(t / j / 47.0) * sin(exp2(mod(a - b, 3.0) / 6.0 + 8.5) * t * j * i + i + j))
      * exp2(-b * 12.0 - 1.0 / b + 6.0 - (i + j) / 3.0);
  }
  return r;
}
//SOUND_END
// --- POST-PROCESSING 2D: MONITOR CRT ---

// gl_FragCoord.xy ci dà i pixel fisici dello schermo, indipendentemente 
// dalla rotazione della telecamera o dell'oggetto 3D!
// Dividiamo per un valore indicativo per normalizzare le coordinate.
vec2 screenUV = gl_FragCoord.xy / 800.0;

// 1. SCANLINES (Righe orizzontali)
// Usiamo lo slider 'A' per regolare al volo la fittezza delle righe (es. range 1-5)
float scanlineDensity = 1500.0;   // edit this to change the scanline density
float scanline = sin(screenUV.y * scanlineDensity) * 0.1 + 0.9;

// 2. FLICKER (Sfarfallio basato sul tempo)
// Lo slider 'B' regola l'intensità dello sfarfallio
float flicker = 1.0 - (0.05 * sin(t * 50.0));   // raise 0.05 for a stronger flicker

// 3. ABERRAZIONE CROMATICA SUI PIXEL DELL'OGGETTO
// Invece di usare un colore solido, sfalsiamo u_col1 per creare l'effetto RGB separato
vec3 col;
col.r = u_col1.r * 1.1; 
col.g = u_col1.g * 0.9;
col.b = u_col1.b * 1.5; // Alziamo il blu per dare un look hi-tech

// 4. BANDE DI SCORRIMENTO (Disturbo verticale)
// Una banda scura che scorre dall'alto verso il basso
float roll = fract(screenUV.y * 0.5 - t * 0.2);
float distortionBand = smoothstep(0.4, 0.5, roll) - smoothstep(0.5, 0.6, roll);

// Abbassiamo la luminosità dove passa la banda
col *= 1.0 - (distortionBand * 0.3);

// 5. APPLICAZIONE DEI FILTRI 2D
vec3 finalColor = col * scanline * flicker;

return finalColor;

